/**
 * In-memory test fixtures for the S-7 rule tests (docs/design/S-7.md decision 16).
 *
 * Origin and usage rights: every buffer here is generated by this file at test
 * time. The audio is a synthetic sine tone computed below; no recorded or
 * third-party audio is used, and no binary fixture is committed. The project
 * owns the output outright.
 */

/** Sample rate for generated WAVs. Low, to keep a 61 s file under 1 MB. */
const SAMPLE_RATE = 8_000;
const BYTES_PER_SAMPLE = 2; // 16-bit PCM, mono
const HEADER_BYTES = 44;

/**
 * Builds a mono 16-bit PCM WAV of exactly `seconds` length (to the nearest
 * sample, i.e. 1/8000 s), filled with a quiet 440 Hz tone.
 * 60.04 s is exactly 480 320 samples, so the decision-10 boundary case is exact.
 */
export function makeWav(seconds: number): Buffer {
  const sampleCount = Math.round(seconds * SAMPLE_RATE);
  const dataBytes = sampleCount * BYTES_PER_SAMPLE;
  const buf = Buffer.alloc(HEADER_BYTES + dataBytes);

  buf.write("RIFF", 0, "ascii");
  buf.writeUInt32LE(36 + dataBytes, 4);
  buf.write("WAVE", 8, "ascii");
  buf.write("fmt ", 12, "ascii");
  buf.writeUInt32LE(16, 16); // fmt chunk size
  buf.writeUInt16LE(1, 20); // PCM
  buf.writeUInt16LE(1, 22); // mono
  buf.writeUInt32LE(SAMPLE_RATE, 24);
  buf.writeUInt32LE(SAMPLE_RATE * BYTES_PER_SAMPLE, 28); // byte rate
  buf.writeUInt16LE(BYTES_PER_SAMPLE, 32); // block align
  buf.writeUInt16LE(8 * BYTES_PER_SAMPLE, 34); // bits per sample
  buf.write("data", 36, "ascii");
  buf.writeUInt32LE(dataBytes, 40);

  for (let i = 0; i < sampleCount; i++) {
    const sample = Math.round(0.2 * 32767 * Math.sin((2 * Math.PI * 440 * i) / SAMPLE_RATE));
    buf.writeInt16LE(sample, HEADER_BYTES + i * BYTES_PER_SAMPLE);
  }
  return buf;
}

/**
 * Deterministic pseudo-random bytes (32-bit LCG, fixed seed) that are not a
 * decodable audio file. Deterministic so a failure is reproducible.
 */
export function makeGarbage(length: number, seed = 0x5eed): Buffer {
  const buf = Buffer.alloc(length);
  let state = seed >>> 0;
  for (let i = 0; i < length; i++) {
    state = (Math.imul(state, 1_664_525) + 1_013_904_223) >>> 0;
    buf[i] = state >>> 24;
  }
  // Never let the noise start with a real container signature.
  buf.write("JUNK", 0, "ascii");
  return buf;
}
